window.FACES={1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,",};
(function(){for(const k in window.FACES){const d=window.FACES[k];const i=d.indexOf(',');const mime=d.slice(5,d.indexOf(';'));const bin=atob(d.slice(i+1));const u=new Uint8Array(bin.length);for(let j=0;j<bin.length;j++)u[j]=bin.charCodeAt(j);window.FACES[k]=URL.createObjectURL(new Blob([u],{type:mime}));}})();